namespace AdaptOrDeity.Sim.Modules
{
    /// <summary>A kernel that also gives the exact Jacobian of its rates (generated by kernelgen).</summary>
    public interface IJacobianKernel : IKernel
    {
        /// <summary>
        /// Writes df/dy for instance <paramref name="k"/> into <paramref name="jacobian"/> (states x states): only the
        /// structurally non-zero entries, so the caller clears it first.
        /// </summary>
        void ComputeJacobian(double t, KernelBatch batch, int k, double[,] jacobian);
    }
}
